    Bug 2005770 - remove old "bug 1182264" support code. r=aleca

    Bug 1182264 added this code to fix a mistake by bug 768207.
    Bug 1187072 improved the fix.

    These would only be needed for the calendars used 10 yrs (or rather not used for 10yrs).

    Differential Revision: https://phabricator.services.mozilla.com/D281524

diff --git a/calendar/base/content/calendar-management.js b/calendar/base/content/calendar-management.js
index eea453b3b69..58f16d89d71 100644
--- a/calendar/base/content/calendar-management.js
+++ b/calendar/base/content/calendar-management.js
@@ -125,18 +125,7 @@ async function loadCalendarManager() {

   // Create the home calendar if no calendar exists.
   const calendars = cal.manager.getCalendars();
-  if (calendars.length) {
-    // migration code to make sure calendars, which do not support caching have cache enabled
-    // required to further clean up on top of bug 1182264
-    for (const calendar of calendars) {
-      if (
-        calendar.getProperty("cache.supported") === false &&
-        calendar.getProperty("cache.enabled") === true
-      ) {
-        calendar.deleteProperty("cache.enabled");
-      }
-    }
-  } else {
+  if (!calendars.length) {
     initHomeCalendar();
   }

diff --git a/calendar/base/src/CalCalendarManager.sys.mjs b/calendar/base/src/CalCalendarManager.sys.mjs
index 83e472cf1d9..d1aac97d5b7 100644
--- a/calendar/base/src/CalCalendarManager.sys.mjs
+++ b/calendar/base/src/CalCalendarManager.sys.mjs
@@ -830,15 +830,6 @@ calMgrCalendarObserver.prototype = {
     aOldValue = aOldValue || false;
     aValue = aValue || false;

-    // hack for bug 1182264 to deal with calendars, which have set cache.enabled, but in fact do
-    // not support caching (like storage calendars) - this also prevents enabling cache again
-    if (aCalendar.getProperty("cache.supported") === false) {
-      if (aCalendar.getProperty("cache.enabled") === true) {
-        aCalendar.deleteProperty("cache.enabled");
-      }
-      return;
-    }
-
     if (aOldValue != aValue) {
       // Try to find the current sort order
       const sortOrderPref = Services.prefs.getStringPref("calendar.list.sortOrder", "").split(" ");
